 for(const x of [-1.9,1.9])for(const y of [-.6,.6])for(const z of [-2.4,2.4])clearancePoints.push(new T.Vector3(x,y,z));
 const clearanceFrom=new T.Vector3(),clearanceTo=new T.Vector3(),turnAxis=new T.Vector3(0,1,0);let clearanceIgnore;const physicalBounds=new T.Box3(),partBounds=new T.Box3();
 for(let team=0;team<2;team++)for(let i=0;i<2;i++){const root=new T.Group(),pad=world.pads[team],home=new T.Vector3(pad.x+(i?9:-9),pad.y+3,pad.z+8),id='chariot-'+team+'-'+i,mat=new T.MeshStandardMaterial({color:team?0x493447:0xc4ae73,roughness:1});
  const physicalParts=[],register=mesh=>{mesh.userData.vehicleId=id;mesh.geometry.computeBoundingBox();physicalParts.push(mesh);parts.push(mesh);world.solids.push(mesh);};
  const hull=new T.Mesh(new T.BoxGeometry(3.8,1.2,4.8),mat);root.add(hull);register(hull);
  for(const side of [-1,1]){const wheel=new T.Mesh(new T.TorusGeometry(1.2,.22,4,12),new T.MeshStandardMaterial({color:team?0x8e598d:0xb4fff2,emissive:team?0x45254d:0x247b77,emissiveIntensity:.8,roughness:.6}));wheel.position.set(side*2,-.1,0);wheel.rotation.y=Math.PI/2;root.add(wheel);register(wheel);const wing=new T.Mesh(new T.BoxGeometry(4,.12,2),mat);wing.position.set(side*3,.5,-.5);wing.rotation.z=side*.18;root.add(wing);register(wing);}
  const flame=new T.Mesh(new T.OctahedronGeometry(.65,0),new T.MeshBasicMaterial({color:0xd5fff5}));flame.position.set(0,-1.4,0);root.add(flame);root.position.copy(home);scene.add(root);root.visible=true;
  const canvas=document.createElement('canvas');canvas.width=512;canvas.height=96;const ctx=canvas.getContext('2d');ctx.fillStyle=team?'#251827':'#102d34';ctx.fillRect(0,0,512,96);ctx.strokeStyle=team?'#bd7ca4':'#abfff2';ctx.lineWidth=5;ctx.strokeRect(3,3,506,90);ctx.fillStyle=ctx.strokeStyle;ctx.font='bold 29px monospace';ctx.textAlign='center';ctx.fillText(team?'SHADOW CHARIOT':'FLYING CHARIOT',256,39);ctx.font='24px monospace';ctx.fillText(team?'ENEMY SOLO CRAFT':'BOT BATTLE · R TO BOARD',256,75);const label=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(canvas),depthTest:false}));label.position.y=14;label.scale.set(12,2.25,1);label.visible=false;label.renderOrder=16;root.add(label);vehicles.push({id,team,root,home,hp:260,maxHp:260,seats:[{actor:null}],velocity:new T.Vector3(),physicalParts,collisionHalfSize:new T.Vector3(),collisionOffset:new T.Vector3(),respawnAt:0,flame,label,objectiveApproach:null});}
 function updateBounds(v){v.root.updateWorldMatrix(true,true);physicalBounds.makeEmpty();for(const mesh of v.physicalParts)physicalBounds.union(partBounds.copy(mesh.geometry.boundingBox).applyMatrix4(mesh.matrixWorld));physicalBounds.getSize(v.collisionHalfSize).multiplyScalar(.5);physicalBounds.getCenter(v.collisionOffset).sub(v.root.position);}
 for(const v of vehicles)updateBounds(v);
